//! Dynamic (runtime, type-driven) serialization of [ValueOwned], producing the same bytes as the code generated by
//! `#[derive_shrink_wrap]` for the equivalent Rust types.
//!
//! Every value that is not a top-level one is written the way generated code writes a field (`BufWriter::write`):
//! the size of [Unsized](shrink_wrap::ElementSize::Unsized) types (evolvable structs and enums, `Box`) is recorded in
//! the FIFO of sizes at the back of the buffer, see [TypeOwned::is_unsized]. Top-level values (method return values,
//! property values, stream items) are written without it (`to_ww_bytes`), same as method arguments, which are the
//! fields of an evolvable struct.

use crate::explain::{PartKind, Trace};
use crate::{
    ApiBundleOwned, FieldOwned, FieldsOwned, FieldsValueOwned, FutureVersionOwned, ItemEnumOwned,
    ItemStructOwned, Repr, TypeOwned, ValueOwned,
};
use anyhow::{Result, anyhow, bail};
use shrink_wrap::buf_reader::Cursors;
use shrink_wrap::buf_writer_owned::UnsizedBuilderOwned;
use shrink_wrap::{
    BufReader, BufWriterOwned, DeserializeShrinkWrap, ElementSize, Nibble, OptionAnyVec,
    OptionAnyVecBuilderOwned, UNib32, UVlq32, UVlq64,
};
use std::borrow::Cow;
use std::collections::HashMap;
use ww_numeric::{NumericAnyTypeOwned, NumericBaseType, NumericValue};

impl ValueOwned {
    /// Deserialize one top-level value of type `ty` (as `T::from_ww_bytes_owned` does).
    pub fn des_shrink_wrap_dyn(
        bytes: &[u8],
        ty: &TypeOwned,
        api_bundle: &ApiBundleOwned,
    ) -> Result<Self> {
        let mut rd = BufReader::new(bytes);
        des_inner(&mut rd, ty, api_bundle, &mut Budget::for_bytes(bytes.len()))
    }

    /// Deserialize one value of type `ty` from a shared [BufReader] (as a field of an evolvable struct is read,
    /// or as one item of a sequence of several values packed together, e.g. an `EitherAnyVec` slot through
    /// [EitherAnyVecIter::next_with](shrink_wrap::either_any_vec::EitherAnyVecIter::next_with)): bounded to its
    /// own size first when `ty` is unsized (the reader doesn't overrun into whatever follows).
    pub fn des_shrink_wrap_field_dyn(
        rd: &mut BufReader,
        ty: &TypeOwned,
        api_bundle: &ApiBundleOwned,
    ) -> Result<Self> {
        let mut b = Budget::for_bytes(rd.bytes_left());
        des_field(rd, ty, api_bundle, &mut b)
    }

    /// Serialize as one top-level value of type `ty` (as `to_ww_bytes_owned` does).
    pub fn ser_shrink_wrap_dyn(
        &self,
        ty: &TypeOwned,
        api_bundle: &ApiBundleOwned,
    ) -> Result<Vec<u8>> {
        let mut wr = BufWriterOwned::new();
        ser_inner(&mut wr, self, ty, api_bundle)?;
        Ok(wr.finish_and_take()?)
    }

    /// Serialize values as the fields of an evolvable struct, e.g., method arguments.
    pub fn ser_shrink_wrap_vec_dyn<'i>(
        values: &[ValueOwned],
        types: impl Iterator<Item = &'i TypeOwned>,
        api_bundle: &ApiBundleOwned,
    ) -> Result<Vec<u8>> {
        let mut wr = BufWriterOwned::new();
        let mut values = values.iter();
        for ty in types {
            let value = values
                .next()
                .ok_or(anyhow!("values and types must have the same length"))?;
            ser_field(&mut wr, value, ty, api_bundle)?;
        }
        if values.next().is_some() {
            bail!("values and types must have the same length");
        }
        Ok(wr.finish_and_take()?)
    }

    /// Deserialize the fields of an evolvable struct, e.g., method arguments.
    /// Missing trailing fields (sent by an older version) are an error, their types carry no default.
    pub fn des_shrink_wrap_vec_dyn<'i>(
        bytes: &[u8],
        types: impl Iterator<Item = &'i TypeOwned>,
        api_bundle: &ApiBundleOwned,
    ) -> Result<Vec<Self>> {
        let mut rd = BufReader::new(bytes);
        let mut b = Budget::for_bytes(bytes.len());
        types
            .map(|ty| des_field(&mut rd, ty, api_bundle, &mut b))
            .collect()
    }

    /// Default value of `ty`: zeros, empty lists and strings, `None`, the first variant of an enum (of a
    /// self-referential one, the first that doesn't contain the enum itself). Fails for a value larger than
    /// [DEFAULT_MAX_VALUES] values (a large array), and for a type each value of which contains another one.
    pub fn default(ty: &TypeOwned, api_bundle: &ApiBundleOwned) -> Result<Self> {
        default_in(ty, api_bundle, &mut Budget::new(DEFAULT_MAX_VALUES))
    }

    pub fn default_fields_value(
        fields: &FieldsOwned,
        api_bundle: &ApiBundleOwned,
    ) -> Result<FieldsValueOwned> {
        default_fields_in(fields, api_bundle, &mut Budget::new(DEFAULT_MAX_VALUES))
    }
}

/// Most values [ValueOwned::default] creates.
pub const DEFAULT_MAX_VALUES: usize = 1 << 20;

/// Bounds the work and the memory of a dynamic decode: types (from a device's introspection data) can describe
/// values much larger than their bytes (arrays of empty tuples, one-bit options nested many times, a `Series` of
/// items in constant columns), and values of self-referential types are as deep as their bytes say (types themselves
/// are nested at most [MAX_DEPTH](crate::generics::MAX_DEPTH) deep in a bundle that passed
/// [validate](crate::generics::validate)).
pub(crate) struct Budget {
    /// Values that may still be created.
    values_left: usize,
    /// Memory they may still take: each value its `size_of`, strings and names their bytes.
    bytes_left: usize,
    depth: usize,
    /// Out-of-line definitions whose default is being created ([ValueOwned::default] only): a self-referential type
    /// takes an enum variant or an `Option` that doesn't refer back.
    open: Vec<u32>,
    /// Where each value was read, for [explain](crate::explain) only.
    pub(crate) trace: Option<Box<Trace>>,
}

/// The default value of a self-referential type would refer to itself (through this definition).
#[derive(Debug)]
struct RefersBack(u32);

impl std::fmt::Display for RefersBack {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "type with index {} has no default value: each one contains another one",
            self.0
        )
    }
}

impl std::error::Error for RefersBack {}

/// Values a decode may create: a fixed allowance and a number per byte, enough for bit-packed data in containers.
const VALUES_FIXED: usize = 1 << 16;
const VALUES_PER_BYTE: usize = 64;
/// Most memory the values of one decode take, whatever its size: 64 bytes of input can't become 4 KB of values
/// times 64 K (a few such messages in flight would exhaust a small host, P2401#17oct-1125).
pub const DECODE_MAX_BYTES: usize = 64 << 20;
/// Each value has its own copy of its field or variant name: names count as a value per this many bytes.
const NAME_BYTES_PER_VALUE: usize = 32;
/// Variants of an enum looked through to find the one read count as a value per this many.
pub(crate) const VARIANTS_PER_VALUE: usize = 16;
/// Deepest nesting of a decode (and of [ValueOwned::default]): [MAX_DEPTH](crate::generics::MAX_DEPTH) type levels
/// take up to two calls each, a value of a self-referential type about four per level of the value
/// (`Option<Box<List>>` in `List`: the `Option`, the `Box`, the out-of-line reference and the struct), so a list or
/// a tree about 70 levels deep decodes. Takes up to about 1.25 MiB of stack in a debug build (the deepest shapes
/// measured, 4.4 KiB per call), so a decode fits on a 2 MiB tokio worker with room for the frames above it.
pub const MAX_DECODE_DEPTH: usize = 3 * crate::generics::MAX_DEPTH;

impl Budget {
    fn new(values: usize) -> Self {
        Budget {
            values_left: values,
            bytes_left: DECODE_MAX_BYTES,
            depth: 0,
            open: vec![],
            trace: None,
        }
    }

    pub(crate) fn for_bytes(len: usize) -> Self {
        Self::new(VALUES_FIXED.saturating_add(len.saturating_mul(VALUES_PER_BYTE)))
    }

    fn too_large() -> anyhow::Error {
        anyhow!("value is too large for its size in bytes (malformed type or data)")
    }

    pub(crate) fn take(&mut self, values: usize) -> Result<()> {
        self.values_left = self
            .values_left
            .checked_sub(values)
            .ok_or_else(Self::too_large)?;
        self.bytes(values.saturating_mul(size_of::<ValueOwned>()))
    }

    /// Heap memory of a value: the bytes of a string or a name.
    pub(crate) fn bytes(&mut self, bytes: usize) -> Result<()> {
        self.bytes_left = self
            .bytes_left
            .checked_sub(bytes)
            .ok_or_else(|| anyhow!("value takes more than {DECODE_MAX_BYTES} bytes of memory"))?;
        Ok(())
    }

    /// A copy of a field or variant name, taking its share of values: types (from a device) can have names as long
    /// as their bytes, and values of zero bits (empty tuples in a `Vec`) each get one.
    fn name(&mut self, name: &str) -> Result<String> {
        self.names(name, 1)?;
        Ok(name.to_string())
    }

    /// The share of `count` copies of a name.
    pub(crate) fn names(&mut self, name: &str, count: usize) -> Result<()> {
        self.take((name.len() / NAME_BYTES_PER_VALUE).saturating_mul(count))?;
        self.bytes(name.len().saturating_mul(count))
    }

    /// `count` more copies of `value`: its values and its strings, each time.
    pub(crate) fn copies(&mut self, value: &ValueOwned, count: usize) -> Result<()> {
        let (values, bytes) = value_size(value);
        self.take(values.saturating_mul(count))?;
        self.bytes(bytes.saturating_mul(count))
    }

    /// One level deeper; [leave](Self::leave) after.
    pub(crate) fn enter(&mut self) -> Result<()> {
        if self.depth >= MAX_DECODE_DEPTH {
            bail!("value is nested deeper than {MAX_DECODE_DEPTH} levels");
        }
        self.depth += 1;
        Ok(())
    }

    pub(crate) fn leave(&mut self) {
        self.depth -= 1;
    }

    /// Label of the next value read, when tracing.
    pub(crate) fn label(&mut self, label: impl std::fmt::Display) {
        if let Some(trace) = &mut self.trace {
            trace.label(label.to_string());
        }
    }

    /// `f` on the trace, when tracing.
    pub(crate) fn trace(&mut self, f: impl FnOnce(&mut Trace)) {
        if let Some(trace) = &mut self.trace {
            f(trace);
        }
    }

    /// Forget a label no value took.
    pub(crate) fn drop_label(&mut self) {
        if let Some(trace) = &mut self.trace {
            trace.drop_label();
        }
    }

    /// Where `rd` is, when tracing: the start of a [part](Self::part).
    pub(crate) fn before(&self, rd: &BufReader) -> Option<Cursors> {
        self.trace.as_ref()?.before(rd)
    }

    /// A length, discriminant or flag read since `before`, when tracing.
    pub(crate) fn part(
        &mut self,
        before: Option<Cursors>,
        rd: &BufReader,
        kind: PartKind,
        label: &str,
        value: impl FnOnce() -> ValueOwned,
        align: usize,
    ) {
        if let Some(trace) = &mut self.trace {
            trace.part(before, rd, kind, label, value(), align);
        }
    }

    /// Runs `f` one level deeper, after taking one value.
    fn nested<T>(&mut self, f: impl FnOnce(&mut Self) -> Result<T>) -> Result<T> {
        self.enter()?;
        let result = self.take(1).and_then(|_| f(self));
        self.leave();
        result
    }
}

/// Values in `value` and the bytes of its strings and names: what a copy of it takes. Bounded by what made `value`
/// (a decode, or a default from the bundle), walked without recursion.
fn value_size(value: &ValueOwned) -> (usize, usize) {
    let mut values = 0usize;
    let mut bytes = 0usize;
    let mut stack = vec![value];
    while let Some(v) = stack.pop() {
        values += 1;
        match v {
            ValueOwned::String(s) => bytes += s.len(),
            ValueOwned::Vec(items) | ValueOwned::Array(items) | ValueOwned::Tuple(items) => {
                stack.extend(items)
            }
            ValueOwned::Struct { fields: f } | ValueOwned::Enum { fields: f, .. } => {
                if let ValueOwned::Enum { variant, .. } = v {
                    bytes += variant.len();
                }
                match f {
                    FieldsValueOwned::Named(named) => {
                        for (name, v) in named {
                            bytes += name.len();
                            stack.push(v);
                        }
                    }
                    FieldsValueOwned::Unnamed(unnamed) => stack.extend(unnamed),
                    FieldsValueOwned::Unit => {}
                }
            }
            ValueOwned::Option(Some(inner)) => stack.push(inner),
            ValueOwned::Result(Ok(inner) | Err(inner)) => stack.push(inner),
            _ => {}
        }
    }
    (values, bytes)
}

fn default_in(ty: &TypeOwned, api_bundle: &ApiBundleOwned, b: &mut Budget) -> Result<ValueOwned> {
    b.nested(|b| default_inner(ty, api_bundle, b))
}

fn default_inner(
    ty: &TypeOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<ValueOwned> {
    {
        match ty {
            TypeOwned::Bool => Ok(ValueOwned::Bool(false)),
            TypeOwned::NumericAny(any) => {
                Ok(ValueOwned::Numeric(default_numeric(numeric_base(any))?))
            }
            TypeOwned::OutOfLine { type_idx } => {
                if b.open.contains(&type_idx.0) {
                    return Err(RefersBack(type_idx.0).into());
                }
                let ty = api_bundle.get_ty(type_idx.0)?;
                b.open.push(type_idx.0);
                let value = default_in(ty.0, api_bundle, b);
                b.open.pop();
                value
            }
            TypeOwned::Flag => Err(anyhow!("flag type cannot be created manually")),
            TypeOwned::String => Ok(ValueOwned::String(String::new())),
            TypeOwned::Vec(_) | TypeOwned::Series(_) => Ok(ValueOwned::Vec(vec![])),
            TypeOwned::MaxLen { ty, .. } => default_in(ty, api_bundle, b),
            TypeOwned::Array { len, ty } => {
                let len = len.fixed()? as usize;
                if len == 0 {
                    return Ok(ValueOwned::Array(vec![]));
                }
                let before = b.values_left;
                let item = default_in(ty, api_bundle, b)?;
                // the copies count as much as the first one
                b.take((before - b.values_left).saturating_mul(len - 1))?;
                Ok(ValueOwned::Array(vec![item; len]))
            }
            TypeOwned::Instance { .. } | TypeOwned::Param(_) => Err(not_instantiated(ty)),
            TypeOwned::Tuple(types) => {
                let mut values = vec![];
                for ty in types {
                    values.push(default_in(ty, api_bundle, b)?);
                }
                Ok(ValueOwned::Tuple(values))
            }
            TypeOwned::Struct(item_struct) => Ok(ValueOwned::Struct {
                fields: default_fields_in(&item_struct.fields, api_bundle, b)?,
            }),
            // the first variant that doesn't contain the type itself (`Lit` of `enum Expr { Add(Box<Expr>, ..),
            // Lit(u32) }`)
            TypeOwned::Enum(item_enum) => {
                let mut refers_back = None;
                for variant in &item_enum.variants {
                    match default_fields_in(&variant.fields, api_bundle, b) {
                        Ok(fields) => {
                            return Ok(ValueOwned::Enum {
                                variant: b.name(&variant.ident)?,
                                fields,
                            });
                        }
                        Err(e) if e.is::<RefersBack>() => refers_back = Some(e),
                        Err(e) => return Err(e),
                    }
                }
                Err(refers_back.unwrap_or_else(|| anyhow!("Enum is empty")))
            }
            TypeOwned::Option { .. } => Ok(ValueOwned::Option(None)),
            TypeOwned::Result { ok_ty, .. } => Ok(ValueOwned::Result(Err(Box::new(default_in(
                ok_ty, api_bundle, b,
            )?)))),
            TypeOwned::Box(inner) => Ok(default_in(inner, api_bundle, b)?),
            TypeOwned::Range(base) => Ok(ValueOwned::Range(
                default_numeric(base)?..default_numeric(base)?,
            )),
            TypeOwned::RangeInclusive(base) => Ok(ValueOwned::RangeInclusive(
                default_numeric(base)?..=default_numeric(base)?,
            )),
        }
    }
}

fn default_fields_in(
    fields: &FieldsOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<FieldsValueOwned> {
    {
        match fields {
            FieldsOwned::Named(named) => {
                let mut named_values = vec![];
                for field in named.iter().filter(|f| !f.is_flag()) {
                    let name = b.name(field.ident.as_deref().unwrap_or_default())?;
                    let value = default_in(&field.ty, api_bundle, b)?;
                    named_values.push((name, value));
                }
                Ok(FieldsValueOwned::Named(named_values))
            }
            FieldsOwned::Unnamed(unnamed) => {
                let mut unnamed_values = vec![];
                for field in unnamed {
                    let value = default_in(&field.ty, api_bundle, b)?;
                    unnamed_values.push(value);
                }
                Ok(FieldsValueOwned::Unnamed(unnamed_values))
            }
            FieldsOwned::Unit => Ok(FieldsValueOwned::Unit),
        }
    }
}

/// A generic definition's parameter, or an instance that [instantiate](crate::generics::instantiate) didn't replace
/// (its definition is not known): dynamic code needs concrete types.
pub(crate) fn not_instantiated(ty: &TypeOwned) -> anyhow::Error {
    match ty {
        TypeOwned::Param(idx) => anyhow!(
            "type parameter {} of a generic definition, not an instance of it",
            idx.0
        ),
        _ => anyhow!(
            "instance of a generic type whose definition is not known (or crate::generics::prepare was not run)"
        ),
    }
}

/// Base type of a numeric type, SubType and ShiftScale are serialized as their base type.
pub(crate) fn numeric_base(any: &NumericAnyTypeOwned) -> &NumericBaseType {
    match any {
        NumericAnyTypeOwned::Base(base)
        | NumericAnyTypeOwned::SubType { base, .. }
        | NumericAnyTypeOwned::ShiftScale { base, .. } => base,
    }
}

fn default_numeric(base: &NumericBaseType) -> Result<NumericValue> {
    Ok(match base {
        NumericBaseType::UB(bits) => unsigned_value(bits.0, 0),
        NumericBaseType::IB(bits) => signed_value(bits.0, 0),
        NumericBaseType::F16
        | NumericBaseType::ULeb32
        | NumericBaseType::ULeb64
        | NumericBaseType::ULeb128
        | NumericBaseType::ILeb32
        | NumericBaseType::ILeb64
        | NumericBaseType::ILeb128 => bail!("numeric type {base:?} is not supported yet"),
        base => base.default(),
    })
}

// ---------------------------------------------------------------------------------------------------------------------
// Deserialization

/// Read a value the way generated code reads a field (`BufReader::read`).
pub(crate) fn des_field(
    rd: &mut BufReader,
    ty: &TypeOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<ValueOwned> {
    if ty.is_unsized(api_bundle)? {
        let before = b.before(rd);
        let len = rd.read_rev_len()?;
        b.part(before, rd, PartKind::Size, "size", || unib32(len), 1);
        b.trace(|t| t.align(rd));
        let mut rd = rd.split(len)?;
        let value = des_inner(&mut rd, ty, api_bundle, b)?;
        // padding at its end, or what a newer version added
        b.trace(|t| t.rest(&rd));
        Ok(value)
    } else {
        des_inner(rd, ty, api_bundle, b)
    }
}

pub(crate) fn des_inner(
    rd: &mut BufReader,
    ty: &TypeOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<ValueOwned> {
    let Some(trace) = &mut b.trace else {
        return b.nested(|b| des_ty(rd, ty, api_bundle, b));
    };
    let open = trace.enter(rd, ty, api_bundle);
    let result = b.nested(|b| des_ty(rd, ty, api_bundle, b));
    if let Some(trace) = &mut b.trace {
        trace.leave(open, rd, &result);
    }
    result
}

/// A length or size as a value, for a [Budget::part].
fn unib32(len: usize) -> ValueOwned {
    ValueOwned::Numeric(NumericValue::UNib32(UNib32(len as u32)))
}

fn des_ty(
    rd: &mut BufReader,
    ty: &TypeOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<ValueOwned> {
    match ty {
        TypeOwned::Instance { .. } | TypeOwned::Param(_) => Err(not_instantiated(ty)),
        TypeOwned::Bool => Ok(ValueOwned::Bool(rd.read_bool()?)),
        TypeOwned::NumericAny(numeric_any) => Ok(ValueOwned::Numeric(des_numeric(
            rd,
            numeric_base(numeric_any),
        )?)),
        TypeOwned::OutOfLine { type_idx } => {
            let ty = api_bundle.get_ty(type_idx.0)?.0;
            des_inner(rd, ty, api_bundle, b)
        }
        TypeOwned::Flag => bail!("flag can only be a named field"),
        TypeOwned::String => Ok(ValueOwned::String(rd.read_str()?.to_string())),
        TypeOwned::MaxLen { max_len, ty } => {
            // the length comes first, check it before reading the elements
            let mut peek = *rd;
            let len = peek.read_rev_len()?;
            check_max_len(len, max_len.fixed()?)?;
            des_inner(rd, ty, api_bundle, b)
        }
        TypeOwned::Vec(inner_ty) => {
            let before = b.before(rd);
            let len = rd.read_rev_len()?;
            b.part(before, rd, PartKind::Size, "len", || unib32(len), 1);
            Ok(ValueOwned::Vec(des_items(
                rd,
                len,
                |_| inner_ty,
                api_bundle,
                b,
            )?))
        }
        TypeOwned::Array { len, ty } => Ok(ValueOwned::Array(des_items(
            rd,
            len.fixed()? as usize,
            |_| ty,
            api_bundle,
            b,
        )?)),
        TypeOwned::Tuple(types) => Ok(ValueOwned::Tuple(des_items(
            rd,
            types.len(),
            |i| &types[i],
            api_bundle,
            b,
        )?)),
        TypeOwned::Struct(struct_def) if struct_def.transparent => {
            let fields = des_transparent_field(rd, struct_def, api_bundle, b)?;
            Ok(ValueOwned::Struct { fields })
        }
        TypeOwned::Struct(struct_def) if struct_def.sparse => {
            let fields = des_sparse_fields(rd, &struct_def.fields, api_bundle, b)?;
            Ok(ValueOwned::Struct { fields })
        }
        TypeOwned::Struct(struct_def) => {
            let fields = des_fields(rd, &struct_def.fields, api_bundle, b)?;
            Ok(ValueOwned::Struct { fields })
        }
        TypeOwned::Enum(enum_def) => des_enum(rd, enum_def, api_bundle, b),
        TypeOwned::Option { .. } | TypeOwned::Result { .. } => {
            let before = b.before(rd);
            let flag = rd.read_bool()?;
            b.part(
                before,
                rd,
                PartKind::Flag,
                "flag",
                || ValueOwned::Bool(flag),
                1,
            );
            des_flagged(rd, flag, ty, api_bundle, b)
        }
        // Box<T> is Unsized itself (its size is handled by des_field), T is read directly inside it
        TypeOwned::Box(inner) => des_inner(rd, inner, api_bundle, b),
        TypeOwned::Series(item_ty) => crate::series::des_series(rd, item_ty, api_bundle, b),
        TypeOwned::Range(_) | TypeOwned::RangeInclusive(_) => des_range(rd, ty),
    }
}

/// `len` values, the type of each given by `ty_of` (its index): own function, as all bulky parts of [des_ty], to
/// keep its stack frame small, a value of a self-referential type goes through it at each level.
#[inline(never)]
fn des_items<'t>(
    rd: &mut BufReader,
    len: usize,
    ty_of: impl Fn(usize) -> &'t TypeOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<Vec<ValueOwned>> {
    let mut items = Vec::with_capacity(len.min(rd.bytes_left() + 1));
    for i in 0..len {
        b.label(format_args!("[{i}]"));
        items.push(des_field(rd, ty_of(i), api_bundle, b)?);
    }
    Ok(items)
}

#[inline(never)]
fn des_enum(
    rd: &mut BufReader,
    enum_def: &ItemEnumOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<ValueOwned> {
    {
        {
            let before = b.before(rd);
            let discriminant = match enum_def.repr {
                Repr::Nibble => rd.read_nib_value()? as u32,
                Repr::BitAligned(bits) => rd.read_un32(bits)?,
                Repr::UNib32 => rd.read_unib32()?,
                Repr::ByteAlignedU8 => rd.read_u8()? as u32,
                Repr::ByteAlignedU16 => rd.read_u16()? as u32,
                Repr::ByteAlignedU32 => rd.read_u32()?,
            };
            b.part(
                before,
                rd,
                PartKind::Discriminant,
                "discriminant",
                || ValueOwned::Numeric(NumericValue::U32(discriminant)),
                crate::explain::repr_alignment(&enum_def.repr),
            );
            let position = enum_def
                .variants
                .iter()
                .position(|v| v.discriminant.0 == discriminant);
            b.take(position.unwrap_or(enum_def.variants.len()) / VARIANTS_PER_VALUE)?;
            let Some(variant) = position.map(|idx| &enum_def.variants[idx]) else {
                // a variant from a newer version, read as the derive reads it into the catch-all (EVO-10): an
                // Unsized enum is bounded by its size slot, its fields are skipped with it (SW-16); any other enum
                // can only be read past a unit variant. Without the catch-all the derive fails on it as well; a model
                // from before EVO-10 doesn't say, an Unsized enum is read past then.
                let catch_all = match &enum_def.future_version {
                    Some(FutureVersionOwned::Variant { .. }) => true,
                    Some(FutureVersionOwned::Off) => false,
                    None => matches!(enum_def.size, ElementSize::Unsized),
                };
                if catch_all {
                    return Ok(ValueOwned::Enum {
                        variant: format!("<unknown {discriminant}>"),
                        fields: FieldsValueOwned::Unit,
                    });
                }
                bail!(
                    "enum '{}' does not have a variant with discriminant {discriminant} (newer version or malformed data)",
                    enum_def.ident
                );
            };
            let fields = des_fields(rd, &variant.fields, api_bundle, b)?;
            Ok(ValueOwned::Enum {
                variant: b.name(&variant.ident)?,
                fields,
            })
        }
    }
}

/// Ranges.
#[inline(never)]
fn des_range(rd: &mut BufReader, ty: &TypeOwned) -> Result<ValueOwned> {
    match ty {
        TypeOwned::Range(base) => {
            let start = des_numeric(rd, base)?;
            let end = des_numeric(rd, base)?;
            Ok(ValueOwned::Range(start..end))
        }
        TypeOwned::RangeInclusive(base) => {
            let start = des_numeric(rd, base)?;
            let end = des_numeric(rd, base)?;
            Ok(ValueOwned::RangeInclusive(start..=end))
        }
        _ => bail!("internal: {ty:?} is not a range"),
    }
}

/// Value of an `Option` or `Result` after its flag.
fn des_flagged(
    rd: &mut BufReader,
    flag: bool,
    ty: &TypeOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<ValueOwned> {
    Ok(match ty {
        TypeOwned::Option { some_ty } => ValueOwned::Option(if flag {
            b.label("some");
            Some(Box::new(des_field(rd, some_ty, api_bundle, b)?))
        } else {
            None
        }),
        TypeOwned::Result { ok_ty, err_ty } => ValueOwned::Result(if flag {
            b.label("ok");
            Ok(Box::new(des_field(rd, ok_ty, api_bundle, b)?))
        } else {
            b.label("err");
            Err(Box::new(des_field(rd, err_ty, api_bundle, b)?))
        }),
        _ => bail!(
            "expected Option or Result, got {}",
            type_name(ty, api_bundle)
        ),
    })
}

/// Relocated flags are kept until the field they belong to is read.
fn des_fields(
    rd: &mut BufReader,
    fields: &FieldsOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<FieldsValueOwned> {
    Ok(match fields {
        FieldsOwned::Named(defs) => {
            let mut values = vec![];
            let mut flags: HashMap<&str, Flag> = HashMap::new();
            for (idx, def) in defs.iter().enumerate() {
                let name = def.ident.as_deref().unwrap_or_default();
                if def.is_flag() {
                    let at_end = rd.bytes_left() == 0;
                    let before = b.before(rd);
                    let value = match rd.read_bool() {
                        Ok(flag) => Some(flag),
                        // the field has a default and was added later: missing from older data
                        Err(e)
                            if at_end
                                && e.is_read_eob()
                                && flag_target(defs, idx).is_some_and(|t| t.default.is_some()) =>
                        {
                            None
                        }
                        Err(e) => return Err(e.into()),
                    };
                    if let Some(flag) = value {
                        b.part(
                            before,
                            rd,
                            PartKind::Flag,
                            &format!("{name} flag"),
                            || ValueOwned::Bool(flag),
                            1,
                        );
                    }
                    flags.entry(name).or_insert(Flag { value, at_end });
                    continue;
                }
                let flag = flags.remove(name);
                b.label(name);
                values.push((
                    b.name(name)?,
                    des_struct_field(rd, def, flag, api_bundle, b)?,
                ));
                // a `None` read from a relocated flag reads nothing: its label is not for the next field
                b.drop_label();
            }
            FieldsValueOwned::Named(values)
        }
        FieldsOwned::Unnamed(defs) => {
            let mut values = vec![];
            for (idx, def) in defs.iter().enumerate() {
                b.label(idx);
                values.push(des_struct_field(rd, def, None, api_bundle, b)?);
            }
            FieldsValueOwned::Unnamed(values)
        }
        FieldsOwned::Unit => FieldsValueOwned::Unit,
    })
}

/// The one field of a `transparent` struct (DER-18): the struct has the field's size class, which [des_field] already
/// handled, so the field is read as it is, without a size of its own.
fn des_transparent_field(
    rd: &mut BufReader,
    struct_def: &ItemStructOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<FieldsValueOwned> {
    let def = struct_def.transparent_field()?;
    Ok(match &def.ident {
        Some(name) => {
            b.label(name);
            let value = des_inner(rd, &def.ty, api_bundle, b)?;
            FieldsValueOwned::Named(vec![(b.name(name)?, value)])
        }
        None => {
            b.label(0);
            FieldsValueOwned::Unnamed(vec![des_inner(rd, &def.ty, api_bundle, b)?])
        }
    })
}

/// Every named field value is one of `defs`.
pub(crate) fn check_field_names(
    values: &[(String, ValueOwned)],
    defs: &[FieldOwned],
    path: &str,
) -> Result<()> {
    for (name, _) in values {
        if !defs.iter().any(|d| d.ident.as_deref() == Some(name)) {
            bail!(
                "{path} does not have field '{name}', expected: {}",
                field_names(defs)
            );
        }
    }
    Ok(())
}

/// The value of the named field `def`, if given.
pub(crate) fn find_field<'v>(
    values: &'v [(String, ValueOwned)],
    def: &FieldOwned,
) -> Option<&'v ValueOwned> {
    let name = def.ident.as_deref().unwrap_or_default();
    values.iter().find(|(n, _)| n == name).map(|(_, v)| v)
}

/// What a missing named field is written as: a field with a default its type's default, an `Option` `None`, else
/// an error.
pub(crate) fn missing_field(
    def: &FieldOwned,
    path: &str,
    api_bundle: &ApiBundleOwned,
) -> Result<ValueOwned> {
    Ok(match (&def.default, def.ty.get_in_line(api_bundle)?) {
        (Some(_), _) => ValueOwned::default(&def.ty, api_bundle)?,
        (None, TypeOwned::Option { .. }) => ValueOwned::Option(None),
        _ => bail!(
            "{path}: missing field '{}'",
            def.ident.as_deref().unwrap_or_default()
        ),
    })
}

/// Fields of a `sparse` struct (DER-13): every field is `Option<T>`, one slot of an `OptionAnyVec`, read in slot
/// order with [OptionAnyVecIter::read_slot_with](shrink_wrap::option_any_vec::OptionAnyVecIter::read_slot_with) —
/// the same dynamic decode the observe host client uses for a level's `PropertyUpdate` (TOOL-11).
fn des_sparse_fields(
    rd: &mut BufReader,
    fields: &FieldsOwned,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<FieldsValueOwned> {
    let FieldsOwned::Named(defs) = fields else {
        bail!("a sparse struct must have named fields");
    };
    b.trace(|t| t.align(rd));
    let vec = OptionAnyVec::des_shrink_wrap(rd)?;
    b.trace(|t| t.header(vec.as_bytes(), vec.header_bits()));
    let mut iter = vec.iter();
    let mut values = vec![];
    for def in defs {
        let name = b.name(def.ident.as_deref().unwrap_or_default())?;
        let slot = def
            .slot
            .ok_or_else(|| anyhow!("sparse field '{name}' has no slot"))?;
        let TypeOwned::Option { some_ty } = &def.ty else {
            bail!("sparse field '{name}' must be Option<T>");
        };
        let value = iter.read_slot_with::<ValueOwned, anyhow::Error>(slot.0, |rd| {
            b.label(&name);
            des_field(rd, some_ty, api_bundle, b)
        })?;
        values.push((name, ValueOwned::Option(value.map(Box::new))));
    }
    b.trace(|t| t.rest(iter.values_reader()));
    Ok(FieldsValueOwned::Named(values))
}

/// A relocated flag of an `Option` or `Result` field: `None` when it is missing from the data.
#[derive(Copy, Clone)]
struct Flag {
    value: Option<bool>,
    /// The flag started at the end of the data: it may have been read from padding bits, which are 0.
    at_end: bool,
}

/// Evolved fields with a `#[default = ..]` are read as their default when they start at the end of the data (sent by
/// an older version) and run out of data, any other error is reported (SW-15). `flag`: relocated flag of an `Option`
/// or `Result` field, already read.
fn des_struct_field(
    rd: &mut BufReader,
    def: &FieldOwned,
    flag: Option<Flag>,
    api_bundle: &ApiBundleOwned,
    b: &mut Budget,
) -> Result<ValueOwned> {
    let at_end = rd.bytes_left() == 0;
    let (value, may_be_missing) = match flag {
        Some(Flag { value: None, .. }) => return default_in(&def.ty, api_bundle, b),
        // a flag read as 0 from padding bits: the `Err` value of a `Result` is missing then
        Some(Flag {
            value: Some(flag),
            at_end,
        }) => (
            des_flagged(rd, flag, &def.ty, api_bundle, b),
            at_end && !flag,
        ),
        None => (des_field(rd, &def.ty, api_bundle, b), at_end),
    };
    match value {
        Ok(value) => Ok(value),
        Err(e)
            if def.default.is_some()
                && may_be_missing
                && e.downcast_ref::<shrink_wrap::Error>()
                    .is_some_and(|e| e.is_read_eob()) =>
        {
            default_in(&def.ty, api_bundle, b)
        }
        Err(e) => Err(e),
    }
}

fn des_numeric(rd: &mut BufReader, base_ty: &NumericBaseType) -> Result<NumericValue> {
    Ok(match base_ty {
        NumericBaseType::Nibble => NumericValue::Nibble(rd.read_nib()?),
        NumericBaseType::U8 => NumericValue::U8(rd.read_u8()?),
        NumericBaseType::U16 => NumericValue::U16(rd.read_u16()?),
        NumericBaseType::U32 => NumericValue::U32(rd.read_u32()?),
        NumericBaseType::UNib32 => NumericValue::UNib32(UNib32(rd.read_unib32()?)),
        NumericBaseType::U64 => NumericValue::U64(rd.read_u64()?),
        NumericBaseType::U128 => NumericValue::U128(rd.read_u128()?),
        NumericBaseType::I8 => NumericValue::I8(rd.read_i8()?),
        NumericBaseType::I16 => NumericValue::I16(rd.read_i16()?),
        NumericBaseType::I32 => NumericValue::I32(rd.read_i32()?),
        NumericBaseType::I64 => NumericValue::I64(rd.read_i64()?),
        NumericBaseType::I128 => NumericValue::I128(rd.read_i128()?),
        NumericBaseType::F32 => NumericValue::F32(rd.read_f32()?),
        NumericBaseType::F64 => NumericValue::F64(rd.read_f64()?),
        NumericBaseType::UVlq32 => NumericValue::UVlq32(UVlq32(rd.read_uvlq32()?)),
        NumericBaseType::UVlq64 => NumericValue::UVlq64(UVlq64(rd.read_uvlq64()?)),
        NumericBaseType::UB(bits) => {
            let bits = bits.0;
            unsigned_value(bits, rd.read_un64(bits)?)
        }
        NumericBaseType::IB(bits) => {
            let bits = bits.0;
            let raw = rd.read_un64(bits)?;
            // sign extend
            let shift = 64 - bits as u32;
            let value = ((raw << shift) as i64) >> shift;
            signed_value(bits, value)
        }
        u => bail!("numeric type {u:?} is not supported yet"),
    })
}

/// Smallest standard unsigned value to hold `bits`-bit number.
pub(crate) fn unsigned_value(bits: u8, value: u64) -> NumericValue {
    match bits {
        0..=8 => NumericValue::U8(value as u8),
        9..=16 => NumericValue::U16(value as u16),
        17..=32 => NumericValue::U32(value as u32),
        _ => NumericValue::U64(value),
    }
}

/// Smallest standard signed value to hold `bits`-bit number.
pub(crate) fn signed_value(bits: u8, value: i64) -> NumericValue {
    match bits {
        0..=8 => NumericValue::I8(value as i8),
        9..=16 => NumericValue::I16(value as i16),
        17..=32 => NumericValue::I32(value as i32),
        _ => NumericValue::I64(value),
    }
}

// ---------------------------------------------------------------------------------------------------------------------
// Serialization

/// Write a value the way generated code writes a field (`BufWriter::write`).
fn ser_field(
    wr: &mut BufWriterOwned,
    value: &ValueOwned,
    ty: &TypeOwned,
    api_bundle: &ApiBundleOwned,
) -> Result<()> {
    if ty.is_unsized(api_bundle)? {
        let builder = UnsizedBuilderOwned::new(wr)?;
        ser_inner(wr, value, ty, api_bundle)?;
        builder.finish(wr)?;
    } else {
        ser_inner(wr, value, ty, api_bundle)?;
    }
    Ok(())
}

fn ser_inner(
    wr: &mut BufWriterOwned,
    value: &ValueOwned,
    ty: &TypeOwned,
    api_bundle: &ApiBundleOwned,
) -> Result<()> {
    let mismatch = || anyhow!("expected {}, got {value:?}", type_name(ty, api_bundle));
    match ty {
        TypeOwned::Instance { .. } | TypeOwned::Param(_) => return Err(not_instantiated(ty)),
        TypeOwned::OutOfLine { type_idx } => {
            let ty = api_bundle.get_ty(type_idx.0)?.0;
            ser_inner(wr, value, ty, api_bundle)?;
        }
        TypeOwned::Bool => {
            let ValueOwned::Bool(value) = value else {
                return Err(mismatch());
            };
            wr.write_bool(*value)?;
        }
        TypeOwned::NumericAny(any) => {
            let ValueOwned::Numeric(value) = value else {
                return Err(mismatch());
            };
            ser_numeric(wr, value, numeric_base(any))?;
        }
        TypeOwned::Flag => bail!("flag can only be a named field"),
        TypeOwned::String => {
            let ValueOwned::String(value) = value else {
                return Err(mismatch());
            };
            wr.write_str(value)?;
        }
        TypeOwned::MaxLen { max_len, ty } => {
            let len = match value {
                ValueOwned::String(value) => value.len(),
                ValueOwned::Vec(items) | ValueOwned::Array(items) => items.len(),
                _ => return Err(mismatch()),
            };
            check_max_len(len, max_len.fixed()?)?;
            ser_inner(wr, value, ty, api_bundle)?;
        }
        TypeOwned::Vec(inner_ty) => {
            let (ValueOwned::Vec(items) | ValueOwned::Array(items)) = value else {
                return Err(mismatch());
            };
            wr.write_rev_len(items.len())?;
            for item in items {
                ser_field(wr, item, inner_ty, api_bundle)?;
            }
        }
        TypeOwned::Array { len, ty: inner_ty } => {
            let (ValueOwned::Array(items) | ValueOwned::Vec(items)) = value else {
                return Err(mismatch());
            };
            let len = len.fixed()?;
            if items.len() != len as usize {
                bail!("expected an array of {len} elements, got {}", items.len());
            }
            for item in items {
                ser_field(wr, item, inner_ty, api_bundle)?;
            }
        }
        TypeOwned::Tuple(types) => {
            let ValueOwned::Tuple(values) = value else {
                return Err(mismatch());
            };
            if values.len() != types.len() {
                bail!(
                    "expected a tuple of {} elements, got {}",
                    types.len(),
                    values.len()
                );
            }
            for (value, ty) in values.iter().zip(types) {
                ser_field(wr, value, ty, api_bundle)?;
            }
        }
        TypeOwned::Struct(item_struct) if item_struct.transparent => {
            let ValueOwned::Struct { fields } = value else {
                return Err(mismatch());
            };
            ser_transparent_field(wr, fields, item_struct, api_bundle)?;
        }
        TypeOwned::Struct(item_struct) if item_struct.sparse => {
            let ValueOwned::Struct { fields } = value else {
                return Err(mismatch());
            };
            ser_sparse_fields(
                wr,
                fields,
                &item_struct.fields,
                &item_struct.ident,
                api_bundle,
            )?;
        }
        TypeOwned::Struct(item_struct) => {
            let ValueOwned::Struct { fields } = value else {
                return Err(mismatch());
            };
            ser_fields(
                wr,
                fields,
                &item_struct.fields,
                &item_struct.ident,
                api_bundle,
            )?;
        }
        TypeOwned::Enum(item_enum) => {
            let ValueOwned::Enum { variant, fields } = value else {
                return Err(mismatch());
            };
            let variant_def = item_enum
                .variants
                .iter()
                .find(|v| &v.ident == variant)
                .ok_or_else(|| {
                    anyhow!(
                        "enum {} does not have variant {variant}, expected one of: {}",
                        item_enum.ident,
                        variant_names(item_enum)
                    )
                })?;
            write_discriminant(wr, item_enum, variant_def.discriminant.0)?;
            let path = format!("{}::{}", item_enum.ident, variant_def.ident);
            ser_fields(wr, fields, &variant_def.fields, &path, api_bundle)?;
        }
        TypeOwned::Option { .. } | TypeOwned::Result { .. } => {
            wr.write_bool(flag_of(value, ty, api_bundle)?)?;
            ser_flagged(wr, value, ty, api_bundle)?;
        }
        // Box<T> is Unsized itself (its size is handled by ser_field), T is written directly inside it
        TypeOwned::Box(inner) => ser_inner(wr, value, inner, api_bundle)?,
        TypeOwned::Range(base) => {
            let ValueOwned::Range(range) = value else {
                return Err(mismatch());
            };
            ser_numeric(wr, &range.start, base)?;
            ser_numeric(wr, &range.end, base)?;
        }
        TypeOwned::RangeInclusive(base) => {
            let ValueOwned::RangeInclusive(range) = value else {
                return Err(mismatch());
            };
            ser_numeric(wr, range.start(), base)?;
            ser_numeric(wr, range.end(), base)?;
        }
        TypeOwned::Series(item_ty) => crate::series_write::ser_series(
            wr,
            value,
            item_ty,
            api_bundle,
            shrink_wrap::series::CodecPolicy::SMALLEST,
        )?,
    }
    Ok(())
}

/// Flag of an `Option` or `Result` value: is some or is ok.
fn flag_of(value: &ValueOwned, ty: &TypeOwned, api_bundle: &ApiBundleOwned) -> Result<bool> {
    match (ty, value) {
        (TypeOwned::Option { .. }, ValueOwned::Option(value)) => Ok(value.is_some()),
        (TypeOwned::Result { .. }, ValueOwned::Result(value)) => Ok(value.is_ok()),
        _ => bail!("expected {}, got {value:?}", type_name(ty, api_bundle)),
    }
}

/// `Option` or `Result` value without its flag.
fn ser_flagged(
    wr: &mut BufWriterOwned,
    value: &ValueOwned,
    ty: &TypeOwned,
    api_bundle: &ApiBundleOwned,
) -> Result<()> {
    match (ty, value) {
        (TypeOwned::Option { some_ty }, ValueOwned::Option(value)) => {
            if let Some(value) = value {
                ser_field(wr, value, some_ty, api_bundle)?;
            }
        }
        (TypeOwned::Result { ok_ty, err_ty }, ValueOwned::Result(value)) => match value {
            Ok(value) => ser_field(wr, value, ok_ty, api_bundle)?,
            Err(value) => ser_field(wr, value, err_ty, api_bundle)?,
        },
        _ => bail!("expected {}, got {value:?}", type_name(ty, api_bundle)),
    }
    Ok(())
}

/// Field a relocated flag at `defs[flag_idx]` belongs to.
fn flag_target(defs: &[FieldOwned], flag_idx: usize) -> Option<&FieldOwned> {
    let ident = &defs[flag_idx].ident;
    defs[flag_idx + 1..]
        .iter()
        .find(|d| &d.ident == ident && !d.is_flag())
}

pub(crate) fn type_name(ty: &TypeOwned, api_bundle: &ApiBundleOwned) -> String {
    ty.human_name(false, api_bundle)
        .unwrap_or_else(|_| format!("{ty:?}"))
}

pub(crate) fn variant_names(item_enum: &ItemEnumOwned) -> String {
    item_enum
        .variants
        .iter()
        .map(|v| v.ident.as_str())
        .collect::<Vec<_>>()
        .join(", ")
}

fn write_discriminant(
    wr: &mut BufWriterOwned,
    item_enum: &ItemEnumOwned,
    discriminant: u32,
) -> Result<()> {
    let max = match item_enum.repr {
        Repr::Nibble => 0xF,
        Repr::BitAligned(bits) if bits < 32 => (1u32 << bits) - 1,
        Repr::BitAligned(_) | Repr::UNib32 | Repr::ByteAlignedU32 => u32::MAX,
        Repr::ByteAlignedU8 => u8::MAX as u32,
        Repr::ByteAlignedU16 => u16::MAX as u32,
    };
    if discriminant > max {
        bail!(
            "enum {} discriminant {discriminant} does not fit into its repr {:?}",
            item_enum.ident,
            item_enum.repr
        );
    }
    match item_enum.repr {
        Repr::Nibble => wr.write_nib_masked(discriminant as u8)?,
        Repr::BitAligned(bits) => wr.write_un32(bits, discriminant)?,
        Repr::UNib32 => wr.write_unib32(discriminant)?,
        Repr::ByteAlignedU8 => wr.write_u8(discriminant as u8)?,
        Repr::ByteAlignedU16 => wr.write_u16(discriminant as u16)?,
        Repr::ByteAlignedU32 => wr.write_u32(discriminant)?,
    }
    Ok(())
}

/// Named fields are matched by name, a missing one can only be an `Option` (written as `None`) or a field with a
/// default value.
fn ser_fields(
    wr: &mut BufWriterOwned,
    fields: &FieldsValueOwned,
    fields_def: &FieldsOwned,
    path: &str,
    api_bundle: &ApiBundleOwned,
) -> Result<()> {
    match (fields_def, fields) {
        (FieldsOwned::Named(defs), FieldsValueOwned::Named(values)) => {
            check_field_names(values, defs, path)?;
            let field_value = |def: &FieldOwned| -> Result<Cow<ValueOwned>> {
                match find_field(values, def) {
                    Some(value) => Ok(Cow::Borrowed(value)),
                    None => Ok(Cow::Owned(missing_field(def, path, api_bundle)?)),
                }
            };
            for (idx, def) in defs.iter().enumerate() {
                if def.is_flag() {
                    let target = flag_target(defs, idx).ok_or_else(|| {
                        anyhow!("{path}: flag of a missing field {:?}", def.ident)
                    })?;
                    let value = field_value(target)?;
                    wr.write_bool(flag_of(&value, &target.ty, api_bundle)?)?;
                    continue;
                }
                let value = field_value(def)?;
                if defs[..idx]
                    .iter()
                    .any(|d| d.is_flag() && d.ident == def.ident)
                {
                    ser_flagged(wr, &value, &def.ty, api_bundle)?;
                } else {
                    ser_field(wr, &value, &def.ty, api_bundle)?;
                }
            }
        }
        (FieldsOwned::Unnamed(defs), FieldsValueOwned::Unnamed(values)) => {
            if defs.len() != values.len() {
                bail!(
                    "{path}: expected {} fields, got {}",
                    defs.len(),
                    values.len()
                );
            }
            for (def, value) in defs.iter().zip(values) {
                ser_field(wr, value, &def.ty, api_bundle)?;
            }
        }
        (FieldsOwned::Unit, FieldsValueOwned::Unit) => {}
        (FieldsOwned::Named(defs), _) => {
            bail!("{path}: expected named fields: {}", field_names(defs))
        }
        (FieldsOwned::Unnamed(defs), _) => {
            bail!("{path}: expected {} unnamed fields", defs.len())
        }
        (FieldsOwned::Unit, _) => bail!("{path}: expected no fields"),
    }
    Ok(())
}

/// The one field of a `transparent` struct (DER-18), written as it is: its size class is the struct's, which
/// [ser_field] already handled.
fn ser_transparent_field(
    wr: &mut BufWriterOwned,
    fields: &FieldsValueOwned,
    item_struct: &ItemStructOwned,
    api_bundle: &ApiBundleOwned,
) -> Result<()> {
    let def = item_struct.transparent_field()?;
    let path = &item_struct.ident;
    let value = match fields {
        FieldsValueOwned::Named(values) if def.ident.is_some() => {
            check_field_names(values, std::slice::from_ref(def), path)?;
            find_field(values, def).ok_or_else(|| {
                anyhow!(
                    "{path}: missing field '{}'",
                    def.ident.as_deref().unwrap_or_default()
                )
            })?
        }
        FieldsValueOwned::Unnamed(values) if def.ident.is_none() => match values.as_slice() {
            [value] => value,
            _ => bail!("{path}: expected 1 unnamed field, got {}", values.len()),
        },
        _ if def.ident.is_some() => bail!("{path}: expected named fields: {}", field_names(std::slice::from_ref(def))),
        _ => bail!("{path}: expected 1 unnamed field"),
    };
    ser_inner(wr, value, &def.ty, api_bundle)
}

/// Fields of a `sparse` struct (DER-13): every field is `Option<T>`, written as one slot of an `OptionAnyVec` in
/// slot order, only the present ones (`Some`) taking space.
fn ser_sparse_fields(
    wr: &mut BufWriterOwned,
    fields: &FieldsValueOwned,
    fields_def: &FieldsOwned,
    path: &str,
    api_bundle: &ApiBundleOwned,
) -> Result<()> {
    let FieldsOwned::Named(defs) = fields_def else {
        bail!("{path}: a sparse struct must have named fields");
    };
    let FieldsValueOwned::Named(values) = fields else {
        bail!("{path}: expected named fields: {}", field_names(defs));
    };
    for (name, _) in values {
        if !defs.iter().any(|d| d.ident.as_deref() == Some(name)) {
            bail!(
                "{path} does not have field '{name}', expected: {}",
                field_names(defs)
            );
        }
    }
    let value_of = |def: &FieldOwned| -> Result<&ValueOwned> {
        let name = def.ident.as_deref().unwrap_or_default();
        values
            .iter()
            .find(|(n, _)| n == name)
            .map(|(_, v)| v)
            .ok_or_else(|| anyhow!("{path}: missing field '{name}'"))
    };
    let present = defs
        .iter()
        .filter_map(|def| match value_of(def) {
            Ok(ValueOwned::Option(Some(_))) => def.slot.map(|s| Ok(s.0)),
            Ok(_) => None,
            Err(e) => Some(Err(e)),
        })
        .collect::<Result<Vec<u32>>>()?;
    let mut builder = OptionAnyVecBuilderOwned::new(wr, present)?;
    for def in defs {
        let name = def.ident.as_deref().unwrap_or_default();
        let ValueOwned::Option(value) = value_of(def)? else {
            bail!("{path}: sparse field '{name}' must be an Option");
        };
        let Some(value) = value else {
            continue;
        };
        let TypeOwned::Option { some_ty } = &def.ty else {
            bail!("{path}: sparse field '{name}' must be Option<T>");
        };
        let slot = def
            .slot
            .ok_or_else(|| anyhow!("{path}: sparse field '{name}' has no slot"))?;
        builder.start_slot(slot.0)?;
        ser_field(wr, value, some_ty, api_bundle)?;
    }
    builder.finish(wr)?;
    Ok(())
}

fn field_names(defs: &[FieldOwned]) -> String {
    defs.iter()
        .filter(|d| !d.is_flag())
        .filter_map(|d| d.ident.as_deref())
        .collect::<Vec<_>>()
        .join(", ")
}

fn ser_numeric(
    wr: &mut BufWriterOwned,
    value: &NumericValue,
    base_ty: &NumericBaseType,
) -> Result<()> {
    let out_of_range = || anyhow!("{value:?} is out of range for {base_ty:?}");
    macro_rules! int {
        ($t:ty) => {
            <$t>::try_from(int_value(value)?).map_err(|_| out_of_range())?
        };
    }
    match base_ty {
        NumericBaseType::Nibble => {
            let nib = Nibble::new(int!(u8)).ok_or_else(out_of_range)?;
            wr.write_nib(nib)?
        }
        NumericBaseType::U8 => wr.write_u8(int!(u8))?,
        NumericBaseType::U16 => wr.write_u16(int!(u16))?,
        NumericBaseType::U32 => wr.write_u32(int!(u32))?,
        NumericBaseType::UNib32 => wr.write_unib32(int!(u32))?,
        NumericBaseType::U64 => wr.write_u64(int!(u64))?,
        NumericBaseType::U128 => match value {
            NumericValue::U128(v) => wr.write_u128(*v)?,
            _ => wr.write_u128(int!(u128))?,
        },
        NumericBaseType::I8 => wr.write_i8(int!(i8))?,
        NumericBaseType::I16 => wr.write_i16(int!(i16))?,
        NumericBaseType::I32 => wr.write_i32(int!(i32))?,
        NumericBaseType::I64 => wr.write_i64(int!(i64))?,
        NumericBaseType::I128 => wr.write_i128(int!(i128))?,
        NumericBaseType::F32 => wr.write_f32(float_value(value)? as f32)?,
        NumericBaseType::F64 => wr.write_f64(float_value(value)?)?,
        NumericBaseType::UVlq32 => wr.write_uvlq32(int!(u32))?,
        NumericBaseType::UVlq64 => wr.write_uvlq64(int!(u64))?,
        NumericBaseType::UB(bits) => {
            let bits = bits.0;
            let v = int!(u64);
            if bits < 64 && v >> bits != 0 {
                return Err(out_of_range());
            }
            wr.write_un64(bits, v)?
        }
        NumericBaseType::IB(bits) => {
            let bits = bits.0;
            let v = int!(i64);
            let (min, max) = (-(1i128 << (bits - 1)), (1i128 << (bits - 1)) - 1);
            if (v as i128) < min || (v as i128) > max {
                return Err(out_of_range());
            }
            let mask = if bits == 64 {
                u64::MAX
            } else {
                (1u64 << bits) - 1
            };
            wr.write_un64(bits, v as u64 & mask)?
        }
        u => bail!("numeric type {u:?} is not supported yet"),
    }
    Ok(())
}

/// Integer value of any integer variant, so that e.g. `U8(1)` can be written as `u32`. Range is checked by the caller.
pub(crate) fn int_value(value: &NumericValue) -> Result<i128> {
    Ok(match value {
        NumericValue::Nibble(v) => v.value() as i128,
        NumericValue::U8(v) => *v as i128,
        NumericValue::U16(v) => *v as i128,
        NumericValue::U32(v) => *v as i128,
        NumericValue::UNib32(v) => v.0 as i128,
        NumericValue::U64(v) => *v as i128,
        NumericValue::U128(v) => i128::try_from(*v).map_err(|_| anyhow!("{v} is out of range"))?,
        NumericValue::I8(v) => *v as i128,
        NumericValue::I16(v) => *v as i128,
        NumericValue::I32(v) => *v as i128,
        NumericValue::I64(v) => *v as i128,
        NumericValue::I128(v) => *v,
        NumericValue::UVlq32(v) => v.0 as i128,
        NumericValue::UVlq64(v) => v.0 as i128,
        u => bail!("expected an integer, got {u:?}"),
    })
}

pub(crate) fn float_value(value: &NumericValue) -> Result<f64> {
    Ok(match value {
        NumericValue::F32(v) => *v as f64,
        NumericValue::F64(v) => *v,
        other => int_value(other)? as f64,
    })
}

/// A [MaxLen](TypeOwned::MaxLen) value of `len` elements: an error if it is longer than `max_len`, never cut.
fn check_max_len(len: usize, max_len: u32) -> Result<()> {
    if len > max_len as usize {
        return Err(anyhow::Error::new(shrink_wrap::Error::MaxLenExceeded)
            .context(format!("{len} elements, at most {max_len} allowed")));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{ItemEnumOwned, VariantOwned};

    fn mode(size: ElementSize, future_version: Option<FutureVersionOwned>, n: u32) -> TypeOwned {
        let fields = |d| match d {
            1 => FieldsOwned::Unnamed(vec![FieldOwned {
                ident: None,
                default: None,
                since: None,
                ty: TypeOwned::Bool,
                docs: vec![],
                slot: None,
                series_opaque: false,
            }]),
            _ => FieldsOwned::Unit,
        };
        TypeOwned::Enum(ItemEnumOwned {
            size,
            repr: Repr::UNib32,
            crate_idx: UNib32(0),
            docs: vec![],
            ident: "Mode".into(),
            generics: vec![],
            variants: (0..n)
                .map(|d| VariantOwned {
                    docs: vec![],
                    ident: ["A", "B", "C", "D"][d as usize].into(),
                    fields: fields(d),
                    discriminant: UNib32(d),
                    since: None,
                })
                .collect(),
            path: None,
            instance_of: None,
            future_version,
        })
    }

    /// EVO-10: a variant from a newer version is read as the derive reads it, into the catch-all when there is one.
    #[test]
    fn newer_variant_is_read_as_the_derive_does() {
        let bundle = crate::fuzz_series::bundle_of(vec![], vec![]);
        let unknown = |variant: &str| ValueOwned::Enum {
            variant: variant.into(),
            fields: FieldsValueOwned::Unit,
        };
        let catch_all = Some(FutureVersionOwned::Variant {
            ident: "Unknown".into(),
        });
        for size in [ElementSize::Unsized, ElementSize::SelfDescribing] {
            let newer = mode(size, catch_all.clone(), 4);
            let bytes = unknown("D").ser_shrink_wrap_dyn(&newer, &bundle).unwrap();
            let read = |future_version| {
                ValueOwned::des_shrink_wrap_dyn(&bytes, &mode(size, future_version, 3), &bundle)
            };
            assert_eq!(read(catch_all.clone()).unwrap(), unknown("<unknown 3>"));
            let err = read(Some(FutureVersionOwned::Off)).unwrap_err().to_string();
            assert!(
                err.contains("does not have a variant with discriminant 3"),
                "{err}"
            );
            // a model from before EVO-10: Unsized enums are read past, as before
            let before = read(None);
            match size {
                ElementSize::Unsized => assert_eq!(before.unwrap(), unknown("<unknown 3>")),
                _ => assert!(before.is_err()),
            }
        }
    }
}
